<script lang="ts">
 import {auth} from '#lib/auth.svelte.ts';import {anyApi} from 'convex/server';import {untrack} from 'svelte';
 let rows=$state<any[]>([]),cases=$state<any[]>([]),status=$state(''),reference=$state(''),cursor=$state<string|null>(null),caseCursor=$state<string|null>(null),done=$state(false),casesDone=$state(false),busy=$state(false),error=$state(''),message=$state(''),kind=$state('payment_review'),reason=$state(''),hold=$state(false),resolutions=$state<Record<string,string>>({}),restore=$state<Record<string,boolean>>({});
 const date=(n:number)=>new Date(n).toLocaleString('en-NG',{timeZone:'Africa/Lagos'});
 async function load(reset=true){if(!auth.client)return;busy=true;error='';try{const result=await auth.client.query(anyApi.paymentOps.list,{paginationOpts:{numItems:25,cursor:reset?null:cursor},...(status?{status}:{}),...(reference.trim()?{reference:reference.trim()}:{})});rows=reset?result.page:[...rows,...result.page];cursor=result.continueCursor;done=result.isDone;if(reset)await loadCases(true);}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function loadCases(reset=false){if(!auth.client)return;const result=await auth.client.query(anyApi.paymentOps.cases,{paginationOpts:{numItems:25,cursor:reset?null:caseCursor}});cases=reset?result.page:[...cases,...result.page];caseCursor=result.continueCursor;casesDone=result.isDone;}
 $effect(()=>{if(auth.client)untrack(()=>void load());});
 async function act(task:()=>Promise<unknown>,refresh=true){busy=true;error='';message='';try{await task();message='Operation recorded.';if(refresh)await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<svelte:head><title>Payment operations — PuntersEdge</title></svelte:head>
<header><h1 class="text-3xl font-bold">Payment operations</h1><p class="mt-3 text-haze">Search attempts, request a server-side provider check and track refunds or disputes. These controls do not issue refunds or move money. Complete financial decisions in the provider dashboard and record the reference here.</p></header>
{#if error}<p role="alert" class="surface mt-4 p-4 text-loss">{error}</p>{/if}{#if message}<p role="status" class="mt-4 text-model">{message}</p>{/if}
<form class="surface mt-5 grid gap-4 p-5 sm:grid-cols-3" onsubmit={e=>{e.preventDefault();void load();}}><label>Status<select class="field mt-2 w-full" bind:value={status}><option value="">All attempts</option>{#each ['pending','paid','failed','initialization_failed'] as value}<option value={value}>{value.replaceAll('_',' ')}</option>{/each}</select></label><label>Exact reference<input class="field mt-2 w-full" bind:value={reference} maxlength="100"/></label><button class="btn-primary self-end" disabled={busy}>Search payments</button></form>
<div class="mt-5 grid gap-4 lg:grid-cols-2">{#each rows as payment}<article class="surface min-w-0 p-5"><h2 class="font-bold capitalize">{payment.provider} · {payment.status.replaceAll('_',' ')}</h2><p class="mt-2 break-all text-sm">{payment.reference}</p><p class="mt-2 text-book">₦{payment.amount.toLocaleString('en-NG')}{payment.diagnostic?' · Diagnostic, not revenue':''}</p><p class="mt-2 text-sm text-haze">{date(payment.createdAt)} · User {payment.userId}</p>{#if payment.stale}<p class="mt-2 font-semibold text-book">Pending over one hour · review needed</p>{/if}<button class="btn-ghost mt-3" disabled={busy||payment.status==='paid'} onclick={()=>act(()=>auth.client!.action(anyApi.paymentOps.check,{reference:payment.reference}))}>Check provider status</button><button class="btn-ghost mt-3" onclick={()=>reference=payment.reference}>Use reference in review</button></article>{:else}<p class="surface p-5 text-haze">{busy?'Loading payments…':'No attempts match these filters.'}</p>{/each}</div>{#if !done}<button class="btn-ghost mt-4" disabled={busy} onclick={()=>load(false)}>Load more payments</button>{/if}
<details class="surface mt-5 p-5"><summary class="min-h-11 cursor-pointer font-bold">Open payment review</summary><form class="mt-4 grid gap-4" onsubmit={e=>{e.preventDefault();void act(()=>auth.client!.mutation(anyApi.paymentOps.openCase,{reference,kind,reason,holdAccess:hold}));}}><label>Payment reference<input class="field mt-2 w-full" bind:value={reference}/></label><label>Review type<select class="field mt-2 w-full" bind:value={kind}><option value="payment_review">Payment review</option><option value="refund">Refund</option><option value="chargeback">Chargeback</option></select></label><label>Reason and provider case reference<textarea class="field mt-2 w-full" bind:value={reason} maxlength="500" rows="3"></textarea></label><label><input type="checkbox" bind:checked={hold}/> Suspend this member's access during review</label><button class="btn-primary" disabled={busy}>Create audited review</button></form></details>
<details class="surface mt-5 p-5"><summary class="min-h-11 cursor-pointer font-bold">Refund & dispute inbox</summary><div class="mt-4 grid gap-4">{#each cases as review}<article class="rounded-xl border border-line p-4"><h2 class="font-bold">{review.kind.replaceAll('_',' ')} · {review.status}</h2><p class="mt-2 break-all text-sm">{review.reference}</p><p class="mt-2 text-sm text-haze">{review.reason}</p>{#if review.status==='open'}<label class="mt-3 block">Decision and provider reference<textarea class="field mt-2 w-full" bind:value={resolutions[review._id]} maxlength="500" rows="2"></textarea></label><label class="mt-3 block"><input type="checkbox" bind:checked={restore[review._id]}/> Restore access held by this review</label><button class="btn-primary mt-3" disabled={busy} onclick={()=>act(()=>auth.client!.mutation(anyApi.paymentOps.resolveCase,{id:review._id,resolution:resolutions[review._id]??'',restoreAccess:!!restore[review._id]}))}>Resolve review</button>{:else}<p class="mt-3 text-model">{review.resolution}</p>{/if}</article>{:else}<p class="text-haze">No payment reviews recorded.</p>{/each}</div>{#if !casesDone}<button class="btn-ghost mt-4" onclick={()=>act(()=>loadCases(),false)}>Load more reviews</button>{/if}</details>
